using System;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports.Editor;
namespace LWS.TruckSumo.Editor {
public static class SumoGoddessAuthoring {
 public static void Install(SumoMatch match){foreach(var fighter in match.fighters)FrontCostume(fighter);if(match.replay!=null&&match.replay.sources!=null)for(int i=0;i<match.replay.sources.Length;i++){var source=match.replay.sources[i];var ghost=match.replay.ghosts[i];if(source.GetComponentsInChildren<Transform>(true).Length==ghost.GetComponentsInChildren<Transform>(true).Length)continue;UnityEngine.Object.DestroyImmediate(ghost.gameObject);var copy=LWS.TruckSports.SportsReplayVisuals.Copy(source);copy.name="Recorded render-only "+i;copy.SetActive(false);match.replay.ghosts[i]=copy.transform;}if(match.replay!=null)EditorUtility.SetDirty(match.replay);}
 public static void FrontCostume(SumoFighter fighter){var truck=fighter.truck;var assembly=truck.visuals;var existing=assembly.Find("Front mawashi costume");if(existing!=null)return;var local=SportsRallyAuthoring.BoundsIn(truck.paint.GetComponent<MeshFilter>(),truck.transform);var front=local.max;var center=local.center;var lower=local.min;var parent=new GameObject("Front mawashi costume").transform;parent.SetParent(assembly,false);parent.localPosition=new Vector3(center.x,Mathf.Max(.15f,lower.y),front.z-.2f);var children=new System.Collections.Generic.List<Transform>();foreach(Transform child in assembly)if(child!=parent&&child.name.IndexOf("mawashi",StringComparison.OrdinalIgnoreCase)>=0)children.Add(child);if(children.Count<4)throw new InvalidOperationException("Expected original mawashi mesh pieces; no substitute costume created.");foreach(var child in children)child.SetParent(parent,false);}
 public static void Upgrade(){EditorSceneManager.OpenScene(SumoAuthoring.Scene);var match=UnityEngine.Object.FindAnyObjectByType<SumoMatch>();Install(match);match.overtimeDuration=18;EditorSceneManager.MarkSceneDirty(match.gameObject.scene);EditorSceneManager.SaveScene(match.gameObject.scene);AssetDatabase.SaveAssets();}
}
}
